import json,subprocess;from pathlib import Path;tid='BROWSER-RELOAD-E046';p=Path('control/lifecycle')/(tid+'.json');r=json.loads(p.read_text()) if p.exists() else {};j=subprocess.run(['journalctl','--user','-u','prediction-research-browser-bridge.service','--since','5 minutes ago','--no-pager'],capture_output=True,text=True).stdout.splitlines();hits=[x for x in j if '/discover' in x or '/enqueue' in x];print(json.dumps({'ledger_exists':p.exists(),'state':r.get('state'),'history':[x.get('state') for x in r.get('history',[])],'recent_bridge':hits}))